def next_guess(dimension: int, num_particles: int, distance: int, prev_guess: Optional[List[int]], is_particle: bool) -> List[int]:
    import itertools
    from collections import Counter

    # Helper function to calculate Hamming distance between two vectors
    def hamming_distance(v1: List[int], v2: List[int]) -> int:
        return sum(i != j for i, j in zip(v1, v2))

    # Helper function to generate a valid next guess given the exclusion and distance constraints
    def find_next_guess(excluded_positions: Set[Tuple[int]], candidate: List[int], distance: int) -> Optional[List[int]]:
        if candidate in excluded_positions:
            return None
        valid_next_guesses = []
        for pos in itertools.product([0, 1], repeat=dimension):
            if hamming_distance(candidate, pos) <= distance:
                valid_next_guesses.append(pos)
        return valid_next_guesses

    # Initial exclusion constraint for the previously probed position, if found a particle
    if prev_guess is not None:
        excluded_positions = set(itertools.product([0, 1], repeat=len(prev_guess))) - {tuple(prev_guess)}
        excluded_positions = {tuple(p) for p in excluded_positions if hamming_distance(tuple(prev_guess), p) >= distance}
    else:
        excluded_positions = set()

    next_guess = None
    candidate_positions = itertools.product([0, 1], repeat=dimension)
    for candidate in candidate_positions:
        candidate = list(candidate)
        valid_next_guesses = find_next_guess(excluded_positions, candidate, distance)
        # Filter candidates that meet at least num_particles constraint
        if len(valid_next_guesses) >= num_particles and next_guess is None:
            next_guess = valid_next_guesses[0]
            if len(valid_next_guesses) == num_particles + 1:  # Found enough unique positions satisfying the constraints
                break
    return next_guess

