def next_probe(dimension, num_particles, distance, prev_guess=None, is_particle=False):
    if prev_guess is None:
        # First guess is always [0, 0, ..., 0]
        return [0] * dimension

    # Track known positions
    known_particles = set(tuple(p) for p in prev_guess) if is_particle else None

    def generate_next_candidates(current_guess):
        candidates = []
        for i in range(dimension):
            # Flip the i-th bit of current guess 0 to 1
            candidate1 = current_guess[:i] + [1] + current_guess[i+1:]
            if known_particles:
                # Avoid recently known positions by ensuring minimum distance
                if any(sum(x) != 1 for x in zip(current_guess, candidate1)) and all(s != t for s, t in zip(candidate1, current_guess)):
                    continue
            candidates.append(candidate1)

            # Flip the i-th bit of current guess 1 to 0 where i != 0 (to avoid repetition)
            if current_guess[i] != 0:
                candidate2 = current_guess[:i] + [0] + current_guess[i+1:]
                if known_particles:
                    if candidate2 in known_particles:
                        continue
                candidates.append(candidate2)
        return candidates

    # Convert current guess list to tuple to store in known_particles set
    current_guess_tuple = tuple(prev_guess) if is_particle else None
    candidates = generate_next_candidates(prev_guess)
    guessed_particles = 0

    for candidate in candidates:
        # Probe candidates sequentially, stopping after probing 'num_particles'-1 once guessed successfully
        guessed_particles += 1
        if guessed_particles < num_particles:
            num_particles -= 1
            if is_particle:
                known_particles.add(tuple(candidate))
            else:
                return candidate

    # If not enough particles found, return the first remaining candidate
    return candidates[0]

