def next_guess(dimension, num_particles, distance, prev_guess, is_particle):
    import itertools

    def hamming_distance(a, b):
        return sum(x != y for x, y in zip(a, b))

    class GrayCode:
        @staticmethod
        def generate(n):
            def gray_code(X):
                prefix = X[0]
                prefix ^= 1 & (X[0] ^ 1)
                return [prefix, prefix ^ X[0]]
            return [x for i in range(1 << n) for x in gray_code(GrayCode.generate(n-1))[:2] if i >> (n-1) & 1 ^ 1 == (i >> 0 & 1)]

    def possible_positions(prev_prob, distance):
        candidates = itertools.product([0, 1], repeat=dimension)
        filtered = [p for p in candidates if hamming_distance(p, prev_prob) >= distance]
        return filtered

    if prev_guess is None or not is_particle:
        # Initial distribution exploration based on Gray code
        gray_codes = GrayCode.generate(dimension)
        for code in gray_codes:
            if hamming_distance(prev_guess, tuple(code)) >= distance:
                return list(code)
    elif is_particle:
        prev_tuple = tuple(prev_guess)
        candidates = possible_positions(prev_tuple, distance)
        guesses = [(c, hamming_distance(c, prev_tuple)) for c in candidates]
        # Sort to choose the next candidate with the farthest Hamming distance difference
        guess, _ = max(guesses, key=lambda x: x[1], default=(None, None))
        if guess is not None:
            return list(guess)
    else:
        raise ValueError("Unexpected state: not a valid configuration of num_particles and distance with previous guess-wise evidence.")

