    else:
        potential_next_guesses = set(product([0, 1], repeat=dimension))

    # If we found a particle, we want to move forward to find the next 1
    if is_particle:
        current_position_set = set(prev_guess)
        # Filter for potential positions maintaining the Hamming distance
        next_guesses = [pos for pos in potential_next_guesses if all(sum(a*b for a,b in zip(pos, prev)) ^ pos.count(1) != 0 for prev in current_position_set)]
        # Return the next guess moving as far as possible from previous guesses
        next_guess = next_positions_to_check(next_guesses, distance, prev_guess)
    else:
        # No particle found, we need to explore the unexplored position space
        all_possible_guesses = set(product([0, 1], repeat=dimension))
        # Eliminating guesses that are within the required distance from known particles
        next_position_candidate_set = all_possible_guesses - potential_next_guesses
        # We select the position that has the least chance to overlap with known particles
        next_guess = next(position for position in next_position_candidate_set if all(sum(a*b for a,b in zip(position, prev)) ^ position.count(1) != 0 for prev in prev_guess))
    return next_guess

# To ensure we keep finding new positions while respecting minimum distance
def next_positions_to_check(guesses, distance, prev_guess):
    next_positions = []
    highest_hamming = -1
    for guess in guesses:
        current_hamming = count_hamming_distance(guess, prev_guess, distance)
        if current_hamming > highest_hamming:
            highest_hamming = current_hamming
            next_positions = [guess]
        elif current_hamming == highest_hamming:
            next_positions.append(guess)
    return next_positions

def count_hamming_distance(guess, prev_guess, distance):
    return sum(a != b for a, b in zip(guess, prev_guess))
